-- Motorbike Rental: isolated, public, synthetic demo seed.
-- NEVER apply this file to an existing/user/production database.
-- It explicitly selects RentalPlatformDemo. All credentials are for local demo only.
-- Admin restores the ORIGINAL development default: admin@rentalplatform.vn / Admin@123.
-- Password hashes are Identity V3 PBKDF2 digests reused from the repository's original demo seed.
-- Precondition: RentalPlatform/database-init-mysql.sql and db/gd3_order_item_reviews.sql.
USE `RentalPlatformDemo`;
SET NAMES utf8mb4;
START TRANSACTION;
